import { isPreviewHost, shouldRegisterServiceWorker, type RegistrationContext } from "@/lib/pwa";

// Single registration point for the offline service worker (public/sw.js is
// generated by vite-plugin-pwa at build time). Never call
// navigator.serviceWorker.register anywhere else.
const SW_URL = "/sw.js";

function isEmbedded(): boolean {
  try {
    return window.self !== window.top;
  } catch {
    return true;
  }
}

function readContext(): RegistrationContext {
  return {
    hostname: window.location.hostname.toLowerCase(),
    search: window.location.search,
    isProduction: import.meta.env.PROD,
    isEmbedded: isEmbedded(),
  };
}

function targetsThisWorker(registration: ServiceWorkerRegistration): boolean {
  const script =
    registration.active?.scriptURL ??
    registration.installing?.scriptURL ??
    registration.waiting?.scriptURL;
  if (!script) return false;
  try {
    return new URL(script).pathname === SW_URL;
  } catch {
    return false;
  }
}

async function unregisterAppWorker(): Promise<void> {
  try {
    const registrations = await navigator.serviceWorker.getRegistrations();
    await Promise.all(
      registrations.filter(targetsThisWorker).map((registration) => registration.unregister()),
    );
  } catch {
    // A browser that refuses to list workers keeps the current page working.
  }
}

export async function registerLumenServiceWorker(): Promise<void> {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return;

  const context = readContext();
  if (!shouldRegisterServiceWorker(context)) {
    // Preview and dev keep the newest build, and drop an offline copy left
    // behind by an earlier visit.
    await unregisterAppWorker();
    return;
  }

  try {
    await navigator.serviceWorker.register(SW_URL, { scope: "/" });
  } catch (error) {
    console.error("Não foi possível ativar o modo sem internet:", error);
  }
}

export { isPreviewHost };
